#pragma once#include <CrySystem/ICryPlugin.h>#include <CryEntitySystem/IEntityClass.h>#include "../Interface/ICineCamEditorPreview.h"#include "CineCamEditorLook.h"class CCinematicCameraComponent;class CCinematicCameraPlugin	: public Cry::IEnginePlugin	, public ISystemEventListener	, public ICineCamEditorPreview{public:	CRYINTERFACE_SIMPLE(Cry::IEnginePlugin)	CRYGENERATE_SINGLETONCLASS_GUID(CCinematicCameraPlugin, "CinematicCamera",		"8A3F1C2D-9B4E-4A7F-B2E0-5D6C3F8A1B9E"_cry_guid)	virtual ~CCinematicCameraPlugin();	// Cry::IEnginePlugin	virtual const char* GetName()     const override { return "CinematicCamera"; }	virtual const char* GetCategory() const override { return "CryPlugins"; }	virtual bool Initialize(SSystemGlobalEnvironment& env, const SSystemInitParams& initParams) override;	// Called after ITimeOfDay::Update() and entity updates, before camera is finalised.	// This is the correct place to write E3DPARAM_HDR_EYEADAPTATION_PARAMS so our	// EV compensation overrides the TOD system's value for the current frame.	virtual void UpdateBeforeFinalizeCamera() override;	// ~Cry::IEnginePlugin	// ISystemEventListener	virtual void OnSystemEvent(ESystemEvent event, UINT_PTR wparam, UINT_PTR lparam) override;	// ~ISystemEventListener	// ICineCamEditorPreview - what the Sandbox level-editor viewport is looking through this	// frame (decisions/s9-editor-cinecam-preview.md). Called once per rendered frame, in edit	// mode, from CLevelEditorViewport::OnRender, i.e. AFTER this frame's UpdateBeforeFinalizeCamera	// - so the resolver always acts on the previous frame's answer, which is why it tolerates one	// frame of staleness before falling back to Default.	virtual void SetViewportPreview(ECineCamEditorPreviewMode mode, EntityId entityId, const CCamera& camera) override;	virtual void ClearViewportPreview() override;	// ~ICineCamEditorPreviewprivate:	//! The edit-mode half of UpdateBeforeFinalizeCamera(): resolve the viewport's answer into	//! "who drives the render state this frame" and let that one publish. Three outcomes:	//! a cinecam entity, the plugin-owned editor look, or nobody (stock picture).	void UpdateEditorPreview();	//! One log line per change of preview owner, never per frame.	void LogPreviewOwnerChange(ECineCamEditorPreviewMode mode, const CCinematicCameraComponent* pOwner);	//! The "CineCam" viewport camera: scene referred + automatic adaptation, no entity.	CCineCamEditorLook m_editorLook;	// What the viewport last said. Frame-COUNTER based staleness, never wall clock: the editor	// skips frames when it is idle, throttled or has no level, and a timer would flicker.	ECineCamEditorPreviewMode m_previewMode = ECineCamEditorPreviewMode::Default;	EntityId                  m_previewEntityId = INVALID_ENTITYID;	uint32                    m_previewFrameId = 0;	// Edge-trigger state for the log line.	ECineCamEditorPreviewMode m_loggedPreviewMode = ECineCamEditorPreviewMode::Default;	EntityId                  m_loggedPreviewEntityId = INVALID_ENTITYID;	bool                      m_bLoggedPreviewOnce = false;};